import { cacheTag } from 'next/cache'
import { revalidateTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

async function getCachedProducts() {
  'use cache'
  cacheTag('products')
  return getAllProducts()
}

export default async function Page() {
  const products = await getCachedProducts()

  async function syncLatestCatalog() {
    'use server'
    // ERP/PIM sync can touch thousands of SKUs. Mark the shared catalog
    // stale and let views refresh in the background so admins are not blocked.
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <h1>Product catalog</h1>
      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} — ${product.price}
          </li>
        ))}
      </ul>
    </main>
  )
}
